    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool _isCurrent;

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.StartDate != default;
    }

    private async Task Update(WorkEntryModel updated)
    {
        await OnChanged.InvokeAsync(updated);
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        var updated = _isCurrent ? Entry with { EndDate = null } : Entry;
        await OnChanged.InvokeAsync(updated);
    }

    private static string FormatDate(DateTime? date) =>
        date.HasValue && date.Value != default ? date.Value.ToString("yyyy-MM-dd") : "";

    private static string FormatDate(DateTime date) =>
        date != default ? date.ToString("yyyy-MM-dd") : "";

    private static DateTime ParseDate(object? value) =>
        DateTime.TryParse(value?.ToString(), out var d) ? d : default;

    private static DateTime? ParseNullableDate(object? value) =>
        DateTime.TryParse(value?.ToString(), out var d) ? d : null;
